import{_ as o,o as e,c as r,ah as s}from"./chunks/framework.BMM80GXQ.js";const a="/assets/2.0/images/data-transfer/export-listing.png",n="/assets/2.0/images/data-transfer/create-export-form.png",i="/assets/2.0/images/data-transfer/export-running.png",p="/assets/2.0/images/data-transfer/export-progress.png",f=JSON.parse('{"title":"Export","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/data-transfer/export.md","filePath":"2.0/data-transfer/export.md","lastUpdated":1775051911000}'),l={name:"2.0/data-transfer/export.md"};function d(c,t,g,u,h,m){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Exporting data to save information in files is a common practice for data management, analysis, and sharing. This involves transferring data from a source system into a file format that is suitable for storage, future use, or sharing with others.</p><h3 id="steps-to-add-bulk-export-in-unopim" tabindex="-1">Steps to add Bulk Export in UnoPim <a class="header-anchor" href="#steps-to-add-bulk-export-in-unopim" aria-label="Permalink to &quot;Steps to add Bulk Export in UnoPim&quot;">​</a></h3><p><strong>Step 1:</strong> Go to the Admin panel of UnoPim click on <strong>Data Transfer &gt;&gt; Exports</strong> and click on Create Exports button.</p><p><img src="'+a+'" alt="Export Listing"></p><p><strong>Step 2:</strong> Under general configurations add the below fields.</p><ol><li><p><strong>Code -</strong> Enter the code of your Export process.</p></li><li><p><strong>Type -</strong> Kindly select the type i.e. (Products, Categories) which you want to Export.</p></li><li><p><strong>Filters -</strong> Select the format of the file <strong>(CSV, XLS, XLSX)</strong> as per your requirements from the dropdown.</p></li><li><p><strong>With Media -</strong> Enable or Disable if you need the export data with or without Media.</p></li></ol><p>Now, click on <strong>Save Export</strong> button</p><p><img src="'+n+'" alt="Create Export Form"></p><p>The create export form has a two-panel layout:</p><ul><li><strong>General panel (left)</strong> — Code, Type (Products/Categories)</li><li><strong>Filters panel (right)</strong> — File Format (CSV/XLS/XLSX dropdown), With Media (toggle)</li></ul><p><strong>Step 3:</strong> From the export listing, click the <strong>Export</strong> action icon (play icon) on the row of the export you want to run. This opens the export execution page.</p><p><img src="'+i+'" alt="Export Execution Page"></p><p>The execution page shows a summary of the export configuration:</p><ul><li><strong>Export Profile</strong> — The export code</li><li><strong>File Format</strong> — CSV, XLS, or XLSX</li><li><strong>With Media</strong> — Yes or No</li></ul><p>Click the <strong>Export Now</strong> button to start processing.</p><h2 id="export-tracker" tabindex="-1">Export Tracker <a class="header-anchor" href="#export-tracker" aria-label="Permalink to &quot;Export Tracker&quot;">​</a></h2><p><strong>Step 4:</strong> After clicking Export Now, you are redirected to the <strong>Job Tracker</strong> page which shows real-time progress of your export.</p><p><img src="'+p+'" alt="Export Progress"></p><p>The tracker shows a <strong>step pipeline</strong> with visual progress indicators:</p><table tabindex="0"><thead><tr><th>Step</th><th>Description</th></tr></thead><tbody><tr><td><strong>Queued</strong></td><td>Job is in the queue waiting to be processed</td></tr><tr><td><strong>Validating</strong></td><td>Export configuration is being validated</td></tr><tr><td><strong>Exporting</strong></td><td>Records are being written to the export file</td></tr><tr><td><strong>Complete</strong></td><td>Export finished successfully</td></tr></tbody></table><p>Each step shows a green checkmark when completed. Below the pipeline you can see:</p><ul><li><strong>Success message</strong> — &quot;Job completed successfully&quot; with the total duration</li><li><strong>Records Created / Updated / Deleted</strong> — Exact counts of records exported</li><li><strong>Total Duration</strong> — How long the export took</li><li><strong>Download log</strong> — Download the full export log file</li><li><strong>Download Exported Files</strong> button — Click to download the generated file</li></ul><h3 id="pause-resume-and-cancel-controls" tabindex="-1">Pause, Resume, and Cancel Controls <a class="header-anchor" href="#pause-resume-and-cancel-controls" aria-label="Permalink to &quot;Pause, Resume, and Cancel Controls&quot;">​</a></h3><p>During an active export, <strong>job control buttons</strong> appear in the tracker:</p><ul><li><strong>Pause</strong> — Temporarily halt an in-progress export. The job state is preserved.</li><li><strong>Resume</strong> — Continue a paused export from where it left off.</li><li><strong>Cancel</strong> — Stop an export entirely. Cancelled jobs cannot be resumed.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The pause and resume feature is especially useful for large exports. You can pause a job during peak hours and resume it during off-peak times.</p></div><h2 id="quick-product-export" tabindex="-1">Quick Product Export <a class="header-anchor" href="#quick-product-export" aria-label="Permalink to &quot;Quick Product Export&quot;">​</a></h2><p>UnoPim supports <strong>dynamic management of quick product export jobs</strong>. You can quickly export selected products directly from the product listing:</p><ol><li>Navigate to <strong>Catalog &gt;&gt; Products</strong></li><li>Select the products you want to export (or export all)</li><li>Click on <strong>Quick Export</strong> button in the top-right</li><li>Choose the format (CSV, XLS, XLSX)</li><li>The export will be processed and downloaded</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For large exports, the system uses an <strong>optimized export pipeline</strong> with eager loading and increased batch size (up to 200) for better performance. Category exports have been optimized to avoid memory overload.</p></div><p>So by the above steps you can easily create Export Data in UnoPim.</p>',32)])])}const b=o(l,[["render",d]]);export{f as __pageData,b as default};
